                ['p', ['en' => '<strong>Our programs:</strong> <a href="internal://page/malaria-program">Malaria</a> · <a href="internal://page/immunization-program">Immunization</a> · <a href="internal://page/maternal-child-health-program">Maternal and Child Health</a> · <a href="internal://page/tb-program">Tuberculosis (TB)</a> · <a href="internal://page/hiv-program">HIV</a>', 'id' => '<strong>Program kami:</strong> <a href="internal://page/program-malaria">Malaria</a> · <a href="internal://page/program-imunisasi">Imunisasi</a> · <a href="internal://page/program-kesehatan-ibu-anak">Kesehatan Ibu dan Anak</a> · <a href="internal://page/program-tbc">Tuberkulosis (TBC)</a> · <a href="internal://page/program-hiv">HIV</a>']],
