                ['p', ['en' => '<a href="internal://page/programs">Learn about our work →</a> · <a href="internal://page/credibility">Our credibility →</a>', 'id' => '<a href="internal://page/program">Pelajari kerja kami →</a> · <a href="internal://page/kredibilitas">Kredibilitas kami →</a>']],
                ['p', ['en' => '[ISI-DULU] Donation call to action: waiting for the foundation\'s decision on payment methods.', 'id' => '[ISI-DULU] Ajakan donasi: menunggu keputusan yayasan tentang metode pembayaran.']],
