            'about' => [
                ['h1', ['en' => 'About us', 'id' => 'Tentang kami']],
                ['p', ['en' => '<strong>Our story.</strong> Yayasan Sinar Bhakti Husada was founded in 2014. Most of its founding board were former civil servants working in program development at the Papua Provincial Health Office. The foundation works in social and humanitarian service, especially delivering health services and improving public health.', 'id' => '<strong>Sejarah kami.</strong> Yayasan Sinar Bhakti Husada didirikan pada tahun 2014. Kepengurusan saat pendirian sebagian besar diisi mantan pegawai negeri sipil bidang bina program Dinas Kesehatan Provinsi Papua. Yayasan bergerak di bidang sosial dan kemanusiaan, khususnya pelayanan dan peningkatan derajat kesehatan masyarakat.']],
                ['h2', ['en' => 'Why we exist', 'id' => 'Latar belakang']],
                ['p', ['en' => '<ul><li>Health is a basic human right.</li><li>Access to health services is still limited.</li><li>Health literacy is low.</li><li>Health workers and medical equipment are in short supply.</li><li>The foundation is a partner in finding solutions.</li></ul>', 'id' => '<ul><li>Kesehatan adalah hak dasar manusia.</li><li>Akses layanan masih terbatas.</li><li>Literasi kesehatan rendah.</li><li>Keterbatasan tenaga dan alat kesehatan.</li><li>Yayasan hadir sebagai mitra untuk mencari solusi.</li></ul>']],
                ['p', ['en' => '<strong>Vision.</strong> To optimize the foundation\'s role in involving all stakeholders in health development.', 'id' => '<strong>Visi.</strong> Mengoptimalkan peran yayasan dalam melibatkan semua pemangku kepentingan dalam pembangunan kesehatan.']],
                ['h2', ['en' => 'Mission', 'id' => 'Misi']],
                ['p', ['en' => '<ul><li>Community empowerment</li><li>Health system strengthening</li><li>Improving quality of life</li></ul>', 'id' => '<ul><li>Pemberdayaan masyarakat</li><li>Penguatan sistem kesehatan</li><li>Peningkatan kualitas hidup</li></ul>']],
                ['p', ['en' => '<strong>Our objectives:</strong> improve the level of health · empower communities · strengthen health systems · develop research · improve the health workforce · provide health facilities.', 'id' => '<strong>Tujuan yayasan:</strong> meningkatkan derajat kesehatan · pemberdayaan masyarakat · penguatan sistem kesehatan · pengembangan riset · peningkatan SDM kesehatan · penyediaan sarana kesehatan.']],
                ['p', ['en' => '<strong>What we do:</strong> health system strengthening · health research · technical assistance for health programs · providing equipment · human resource development · health education.', 'id' => '<strong>Bentuk kegiatan:</strong> penguatan sistem kesehatan · riset kesehatan · pendampingan teknis program kesehatan · penyediaan peralatan · peningkatan SDM · edukasi kesehatan.']],
                ['h2', ['en' => 'How we are organized', 'id' => 'Organisasi pelaksana']],
                ['p', ['en' => '<ul><li><strong>Core Team</strong>, coordinated by the Director: Finance Manager, Human Resources and Admin Manager, and Senior Technical Advisor.</li><li><strong>Technical Team</strong>, coordinated by the Program Manager: technical staff for health systems, maternal, neonatal and child health (MNCH), HIV, TB, pharmacy and logistics, malaria, and the Expanded Program on Immunization (EPI).</li><li><strong>Program Team</strong>: four Program Officers (MNCH, EPI, TB–HIV, malaria), who supervise Field Officers.</li><li><strong>Research Division</strong>: memoranda of understanding with five researchers and one university, the Faculty of Public Health of Cenderawasih University (UNCEN), Jayapura.</li><li><strong>Training Team</strong>: coaching for Program Officers and Field Officers, and for government technical agencies, during assignments.</li></ul>', 'id' => '<ul><li><strong>Core Team</strong> dikoordinir oleh Direktur: Finance Manager, Human Resources–Admin Manager, dan Senior Technical Advisor.</li><li><strong>Technical Team</strong> dikoordinir oleh Program Manager: tenaga teknis sistem kesehatan, MNCH (Maternal Neonatal Child Health), HIV, TB, Pharmacy/Logistic, Malaria, dan EPI (Expanded Program Immunization).</li><li><strong>Program Team</strong>: empat Program Officer (MNCH, EPI, TB–HIV, Malaria) yang membawahi Field Officer.</li><li><strong>Tim/Divisi Riset</strong>: MoU dengan lima peneliti dan satu universitas, yaitu FKM Universitas Cenderawasih (UNCEN), Jayapura.</li><li><strong>Tim Training</strong>: coaching bagi PO dan FO, serta bagi instansi teknis pemerintah, saat penugasan.</li></ul>']],
                ['p', ['en' => '<strong>Founding board (2014).</strong> Chair of the Advisory Board: drg. Agnes Ang · Advisory Board members: Saryono, SKM; Sriyana, SKM · Chair of the Supervisory Board: Sriyana, SKM · Supervisory Board member: Julianingsih Bakker · General Chair: I Kadek Hermanta, SKM., M.Si · Secretary: drh. Putu Yuga Andacara · Treasurer: Kusdiyana, S.IKom., MM.', 'id' => '<strong>Susunan pengurus saat pendirian (2014).</strong> Ketua Pembina: drg. Agnes Ang · Anggota Pembina: Saryono, SKM; Sriyana, SKM · Ketua Pengawas: Sriyana, SKM · Anggota Pengawas: Julianingsih Bakker · Ketua Umum: I Kadek Hermanta, SKM., M.Si · Sekretaris: drh. Putu Yuga Andacara · Bendahara: Kusdiyana, S.IKom., MM.']],
                ['p', ['en' => '[ISI-DULU] Confirm current leadership and each person\'s consent to be listed (see notes).', 'id' => '[ISI-DULU] Konfirmasi susunan terkini dan persetujuan tiap orang untuk dicantumkan (lihat catatan).']],
